// The single swap point for the chart backend. Every chart component imports
// from this file only, so switching the whole library is a one-file change.
//
// Default: the dependency-free, hand-rolled engine in this folder.
//
// To use TanStack Charts instead (alpha — pin the exact version):
//   pnpm add @tanstack/charts@0.18.0 @tanstack/vue-charts@0.18.0
// then replace the exports below with:
//
//   export { Chart } from '@tanstack/vue-charts';
//   export { areaY, defineChart, lineY } from '@tanstack/charts';
//   export { pie, polar, radialArc } from '@tanstack/charts/polar';
//   export { scaleLinear } from '@tanstack/charts/scales/linear';
//   export { scalePoint } from '@tanstack/charts/scales/point';
//
// Chart definitions written against this file are valid TanStack Charts
// definitions, so no component code changes.
export { default as Chart } from './Chart.vue';
export {
  areaY,
  defineChart,
  lineY,
  pie,
  polar,
  radialArc,
} from './chart-marks';
export { scaleLinear, scalePoint } from './chart-scales';

// Dependency-free subset of the mark API exported by @tanstack/charts and
// @tanstack/charts/polar. Each builder evaluates its channels while the datum
// type is known and returns a render-ready mark; geometry is resolved later by
// the scene compiler at a concrete size.
import type {
  AreaYMark,
  AreaYOptions,
  CartesianPoint,
  Channel,
  ChartDefinition,
  ChartSpec,
  ChartValue,
  LineYMark,
  LineYOptions,
  PieDatum,
  PieOptions,
  PolarMark,
  PolarOptions,
  RadialArcMark,
  RadialArcOptions,
  TransformValue,
  VisualChannel,
} from './types';

const TAU = Math.PI * 2;

function read<TDatum, TValue>(
  datum: TDatum,
  index: number,
  data: readonly TDatum[],
  channel: Channel<TDatum, TValue> | TransformValue<TDatum, TValue> | undefined,
): unknown {
  if (channel === undefined) return undefined;
  if (typeof channel === 'function') return channel(datum, { index, data });
  return datum[channel];
}

function visual<TDatum>(
  data: readonly TDatum[],
  index: number,
  channel: VisualChannel<TDatum, string> | undefined,
): string | undefined {
  if (typeof channel !== 'function') return channel;
  const datum = data[index];
  return datum === undefined ? undefined : channel(datum, { index, data });
}

const isFiniteNumber = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value);

const isChartValue = (value: unknown): value is ChartValue =>
  isFiniteNumber(value) || typeof value === 'string' || value instanceof Date;

function points<TDatum>(
  data: readonly TDatum[],
  x: Channel<TDatum, ChartValue | null | undefined> | undefined,
  y: Channel<TDatum, number | null | undefined> | undefined,
  y1?: number | Channel<TDatum, number | null | undefined>,
): CartesianPoint[] {
  return data.flatMap((datum, index) => {
    // A missing position channel falls back to the datum index, as in TanStack.
    const xv = x === undefined ? index : read(datum, index, data, x);
    const yv = y === undefined ? index : read(datum, index, data, y);
    if (!isChartValue(xv) || !isFiniteNumber(yv)) return [];
    const base = typeof y1 === 'number' ? y1 : read(datum, index, data, y1);
    return [{ x: xv, y: yv, y1: isFiniteNumber(base) ? base : 0 }];
  });
}

export function defineChart(spec: ChartSpec): ChartDefinition {
  return { marks: spec.marks, scales: spec.scales };
}

export function lineY<TDatum>(
  source: Iterable<TDatum>,
  options: LineYOptions<NoInfer<TDatum>> = {},
): LineYMark {
  const data = Array.from(source);
  return {
    kind: 'lineY',
    id: options.id,
    points: points(data, options.x, options.y),
    stroke: visual(data, 0, options.stroke),
    strokeOpacity: options.strokeOpacity,
    strokeWidth: options.strokeWidth,
    strokeDasharray: options.strokeDasharray,
  };
}

export function areaY<TDatum>(
  source: Iterable<TDatum>,
  options: AreaYOptions<NoInfer<TDatum>> = {},
): AreaYMark {
  const data = Array.from(source);
  return {
    kind: 'areaY',
    id: options.id,
    points: points(data, options.x, options.y, options.y1),
    fill: visual(data, 0, options.fill),
    fillOpacity: options.fillOpacity,
    stroke: visual(data, 0, options.stroke),
    strokeWidth: options.strokeWidth,
  };
}

export function polar(options: PolarOptions): PolarMark {
  return { kind: 'polar', options };
}

export function radialArc<TDatum>(
  source: Iterable<TDatum>,
  options: RadialArcOptions<NoInfer<TDatum>> = {},
): RadialArcMark {
  const data = Array.from(source);
  const slices = data.flatMap((datum, index) => {
    const start = read(datum, index, data, options.startAngle);
    const end = read(datum, index, data, options.endAngle);
    const pad = read(datum, index, data, options.padAngle);
    if (!isFiniteNumber(start) || !isFiniteNumber(end)) return [];
    return [
      {
        startAngle: start,
        endAngle: end,
        padAngle: isFiniteNumber(pad) ? pad : 0,
        fill: visual(data, index, options.fill),
        stroke: visual(data, index, options.stroke),
      },
    ];
  });
  return {
    kind: 'radialArc',
    id: options.id,
    className: options.className,
    slices,
    innerRadius: options.innerRadius,
    outerRadius: options.outerRadius,
    cornerRadius: options.cornerRadius,
    fillOpacity: options.fillOpacity,
    strokeOpacity: options.strokeOpacity,
    strokeWidth: options.strokeWidth,
    opacity: options.opacity,
  };
}

/**
 * Allocates nonnegative values into angular intervals, in input order.
 * Matches TanStack's allocation: gaps sit between positive slices, plus one
 * after the last slice when the sweep is a full revolution.
 */
export function pie<TDatum extends object>(
  source: Iterable<TDatum>,
  options: PieOptions<NoInfer<TDatum>>,
): PieDatum<TDatum>[] {
  const data = Array.from(source);
  const start = options.startAngle ?? 0;
  const end = options.endAngle ?? TAU;
  const gap = options.gapAngle ?? 0;
  const sweep = end - start;
  if (!Number.isFinite(sweep) || Math.abs(sweep) > TAU) {
    throw new TypeError('pie: angular sweep must be no greater than 2π');
  }

  const entries = data.flatMap((datum, index) => {
    const value = read(datum, index, data, options.value);
    if (!isFiniteNumber(value)) return [];
    if (value < 0) {
      throw new TypeError(`pie: value at index ${index} must be nonnegative`);
    }
    return [{ datum, index, value }];
  });

  const full = Math.abs(Math.abs(sweep) - TAU) <= 1e-12;
  const positive = entries.filter((entry) => entry.value > 0).length;
  const gapCount =
    positive === 0 ? 0 : Math.max(0, positive - 1) + (full ? 1 : 0);
  const drawable = Math.abs(sweep) - gapCount * gap;
  if (positive > 0 && drawable <= 0) {
    throw new TypeError('pie: gapAngle leaves insufficient angular space');
  }

  const total = entries.reduce((sum, entry) => sum + entry.value, 0);
  const direction = sweep < 0 ? -1 : 1;
  let cursor = start;
  let remaining = positive;

  return entries.map(({ datum, index, value }, order) => {
    const fraction = total === 0 ? 0 : value / total;
    const sliceStart = cursor;
    let sliceEnd = cursor;
    if (value > 0) {
      remaining -= 1;
      sliceEnd =
        remaining === 0
          ? end - (full ? direction * gap : 0)
          : cursor + direction * drawable * fraction;
      cursor = sliceEnd;
      if (remaining > 0 || full) cursor += direction * gap;
    }
    return {
      ...datum,
      source: [datum],
      sourceIndexes: [index],
      value,
      index: order,
      fraction,
      startAngle: sliceStart,
      endAngle: sliceEnd,
      angle: sliceStart + (sliceEnd - sliceStart) / 2,
      padAngle: 0,
    };
  });
}

// Dependency-free subset of the scales exported by
// @tanstack/charts/scales/linear and @tanstack/charts/scales/point.
// Tick and nice semantics follow d3-scale, which TanStack Charts uses.
import type { LinearScale, PointScale } from './types';

const e10 = Math.sqrt(50);
const e5 = Math.sqrt(10);
const e2 = Math.sqrt(2);

function tickIncrement(start: number, stop: number, count: number): number {
  const step = (stop - start) / Math.max(0, count);
  const power = Math.floor(Math.log10(step));
  const error = step / 10 ** power;
  const factor = error >= e10 ? 10 : error >= e5 ? 5 : error >= e2 ? 2 : 1;
  return power >= 0 ? factor * 10 ** power : -(10 ** -power) / factor;
}

function linearTicks(start: number, stop: number, count: number): number[] {
  if (!(count > 0) || start === stop) return [start];
  const reverse = stop < start;
  const [lo, hi] = reverse ? [stop, start] : [start, stop];
  const inc = tickIncrement(lo, hi, count);
  if (inc === 0 || !Number.isFinite(inc)) return [];
  const ticks: number[] = [];
  if (inc > 0) {
    const i0 = Math.ceil(lo / inc);
    const i1 = Math.floor(hi / inc);
    for (let i = i0; i <= i1; i++) ticks.push(i * inc);
  } else {
    const i0 = Math.ceil(lo * -inc);
    const i1 = Math.floor(hi * -inc);
    for (let i = i0; i <= i1; i++) ticks.push(i / -inc);
  }
  return reverse ? ticks.reverse() : ticks;
}

function toPair(values: Iterable<number>): [number, number] {
  const [a = 0, b = 1] = Array.from(values);
  return [a, b];
}

function createLinear(
  initialDomain: [number, number],
  initialRange: [number, number],
): LinearScale {
  let domain = initialDomain;
  let range = initialRange;
  let clamped = false;

  const scale = ((value: number | null | undefined) => {
    if (value == null || !Number.isFinite(value)) return undefined;
    const [d0, d1] = domain;
    const span = d1 - d0;
    let t = span === 0 ? 0.5 : (value - d0) / span;
    if (clamped) t = Math.min(1, Math.max(0, t));
    return range[0] + t * (range[1] - range[0]);
  }) as LinearScale;

  function domainAccessor(): [number, number];
  function domainAccessor(values: Iterable<number>): LinearScale;
  function domainAccessor(values?: Iterable<number>) {
    if (values === undefined) return [...domain] as [number, number];
    domain = toPair(values);
    return scale;
  }
  function rangeAccessor(): [number, number];
  function rangeAccessor(values: Iterable<number>): LinearScale;
  function rangeAccessor(values?: Iterable<number>) {
    if (values === undefined) return [...range] as [number, number];
    range = toPair(values);
    return scale;
  }
  function clampAccessor(): boolean;
  function clampAccessor(value: boolean): LinearScale;
  function clampAccessor(value?: boolean) {
    if (value === undefined) return clamped;
    clamped = value;
    return scale;
  }

  scale.domain = domainAccessor;
  scale.range = rangeAccessor;
  scale.clamp = clampAccessor;
  scale.invert = (value) => {
    const span = range[1] - range[0];
    const t = span === 0 ? 0.5 : (value - range[0]) / span;
    return domain[0] + t * (domain[1] - domain[0]);
  };
  scale.ticks = (count = 10) => linearTicks(domain[0], domain[1], count);
  scale.tickFormat = (count = 10) => {
    const step = Math.abs(tickIncrement(domain[0], domain[1], count));
    const digits = step > 0 && step < 1 ? Math.ceil(-Math.log10(step)) : 0;
    return (value) => value.toFixed(Math.min(20, Math.max(0, digits)));
  };
  scale.nice = (count = 10) => {
    let [d0, d1] = domain;
    const reverse = d1 < d0;
    if (reverse) [d0, d1] = [d1, d0];
    for (let pass = 0; pass < 10; pass++) {
      const step = tickIncrement(d0, d1, count);
      if (!Number.isFinite(step) || step === 0) break;
      const next: [number, number] =
        step > 0
          ? [Math.floor(d0 / step) * step, Math.ceil(d1 / step) * step]
          : [Math.ceil(d0 * step) / step, Math.floor(d1 * step) / step];
      if (next[0] === d0 && next[1] === d1) break;
      [d0, d1] = next;
    }
    domain = reverse ? [d1, d0] : [d0, d1];
    return scale;
  };
  scale.copy = () => createLinear([...domain], [...range]).clamp(clamped);
  return scale;
}

/**
 * `scaleLinear()`, `scaleLinear(range)` or `scaleLinear(domain, range)`, as in
 * d3-scale: with one argument it is the range.
 */
export function scaleLinear(
  domainOrRange?: Iterable<number>,
  range?: Iterable<number>,
): LinearScale {
  if (domainOrRange === undefined) return createLinear([0, 1], [0, 1]);
  if (range === undefined) return createLinear([0, 1], toPair(domainOrRange));
  return createLinear(toPair(domainOrRange), toPair(range));
}

function createPoint<TDomain extends string | number>(
  initialDomain: TDomain[],
  initialRange: [number, number],
): PointScale<TDomain> {
  let domain = initialDomain;
  let range = initialRange;
  let pad = 0;

  const step = () => {
    const n = domain.length;
    const span = range[1] - range[0];
    return n <= 1 ? 0 : span / Math.max(1, n - 1 + pad * 2);
  };

  const scale = ((value: TDomain | null | undefined) => {
    if (value == null) return undefined;
    const index = domain.indexOf(value);
    if (index < 0) return undefined;
    if (domain.length === 1) return (range[0] + range[1]) / 2;
    return range[0] + step() * (pad + index);
  }) as PointScale<TDomain>;

  function domainAccessor(): TDomain[];
  function domainAccessor(values: Iterable<TDomain>): PointScale<TDomain>;
  function domainAccessor(values?: Iterable<TDomain>) {
    if (values === undefined) return [...domain];
    domain = Array.from(new Set(values));
    return scale;
  }
  function rangeAccessor(): [number, number];
  function rangeAccessor(values: Iterable<number>): PointScale<TDomain>;
  function rangeAccessor(values?: Iterable<number>) {
    if (values === undefined) return [...range] as [number, number];
    range = toPair(values);
    return scale;
  }
  function paddingAccessor(): number;
  function paddingAccessor(value: number): PointScale<TDomain>;
  function paddingAccessor(value?: number) {
    if (value === undefined) return pad;
    pad = value;
    return scale;
  }

  scale.domain = domainAccessor;
  scale.range = rangeAccessor;
  scale.padding = paddingAccessor;
  scale.step = step;
  scale.copy = () => createPoint([...domain], [...range]).padding(pad);
  return scale;
}

/**
 * `scalePoint()`, `scalePoint(range)` or `scalePoint(domain, range)`, as in
 * d3-scale: with one argument it is the range.
 */
export function scalePoint<TDomain extends string | number = string>(
  domainOrRange?: Iterable<TDomain | number>,
  range?: Iterable<number>,
): PointScale<TDomain> {
  if (domainOrRange === undefined) return createPoint<TDomain>([], [0, 1]);
  const values: (TDomain | number)[] = Array.from(domainOrRange);
  if (range === undefined) {
    return createPoint<TDomain>([], toPair(values.filter(isNumber)));
  }
  const domain = values.filter((value): value is TDomain =>
    isDomainValue<TDomain>(value),
  );
  return createPoint<TDomain>(Array.from(new Set(domain)), toPair(range));
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number';
}

function isDomainValue<TDomain extends string | number>(
  value: unknown,
): value is TDomain {
  return typeof value === 'string' || typeof value === 'number';
}

// Compiles a chart definition at a concrete size into renderer-neutral SVG
// primitives. Geometry follows TanStack Charts conventions: polar angle 0 is
// 12 o'clock and increases clockwise; arc corners follow d3-shape's arc.
import type {
  AreaYMark,
  ChartDefinition,
  ChartPositionScaleOptions,
  ChartScaleInstance,
  ChartScene,
  ChartValue,
  LineYMark,
  PointScale,
  PolarLayoutContext,
  PolarLength,
  PolarMark,
  RadialArcMark,
  SceneGridLine,
  ScenePath,
  SceneTick,
} from './types';

const TAU = Math.PI * 2;
const EPSILON = 1e-9;

const round = (n: number) => Math.round(n * 1000) / 1000;
const pt = (x: number, y: number) => `${round(x)},${round(y)}`;

function isPointScale(
  scale: ChartScaleInstance,
): scale is PointScale<string | number> {
  return 'padding' in scale;
}

function instantiate(options: ChartPositionScaleOptions): {
  scale: ChartScaleInstance;
  inferred: boolean;
} {
  const input = options.scale;
  if ('domain' in input) return { scale: input.copy(), inferred: false };
  return { scale: input(), inferred: true };
}

function numeric(value: ChartValue): number {
  return value instanceof Date ? value.getTime() : Number(value);
}

function estimateLabelWidth(text: string): number {
  return text.length * 6.4 + 10;
}

function compileCartesian(
  definition: ChartDefinition,
  marks: readonly (LineYMark | AreaYMark)[],
  width: number,
  height: number,
): Pick<ChartScene, 'grid' | 'ticks' | 'paths'> {
  const xOptions = definition.scales.x;
  const yOptions = definition.scales.y;
  if (!xOptions || !yOptions || marks.length === 0) {
    return { grid: [], ticks: [], paths: [] };
  }

  const all = marks.flatMap((mark) => mark.points);
  const x = instantiate(xOptions);
  const y = instantiate(yOptions);

  if (x.inferred) {
    if (isPointScale(x.scale)) {
      x.scale.domain(
        all.map((p) => (p.x instanceof Date ? p.x.getTime() : p.x)),
      );
    } else {
      const xs = all.map((p) => numeric(p.x));
      x.scale.domain([Math.min(...xs), Math.max(...xs)]);
    }
  }
  if (y.inferred && !isPointScale(y.scale)) {
    const ys = all.flatMap((p) => [p.y]);
    const hasArea = marks.some((mark) => mark.kind === 'areaY');
    if (hasArea) ys.push(...all.map((p) => p.y1));
    y.scale.domain([Math.min(...ys), Math.max(...ys)]);
  }
  // Tick density follows the plot height (about one tick per 60px).
  const yTickCount = Math.max(2, Math.floor((height - 32) / 60));
  if (yOptions.nice && !isPointScale(y.scale)) {
    y.scale.nice(
      typeof yOptions.nice === 'number' ? yOptions.nice : yTickCount,
    );
  }
  if (xOptions.nice && !isPointScale(x.scale)) {
    x.scale.nice(typeof xOptions.nice === 'number' ? xOptions.nice : undefined);
  }

  const showX = xOptions.axis !== false;
  const showY = yOptions.axis !== false;
  const yTicks = isPointScale(y.scale) ? [] : y.scale.ticks(yTickCount);
  const yFormat = isPointScale(y.scale)
    ? String
    : y.scale.tickFormat(yTickCount);
  const maxStroke = Math.max(
    1,
    ...marks.map(
      (mark) => mark.strokeWidth ?? (mark.kind === 'lineY' ? 1.5 : 0),
    ),
  );
  const inset = maxStroke / 2 + 1;
  const left = showY
    ? Math.max(...yTicks.map((t) => estimateLabelWidth(yFormat(t))), 24)
    : inset;
  const bottom = showX ? 24 : inset;
  const top = showY ? 8 : inset;
  const right = showX ? 12 : inset;

  const xRange: [number, number] = xOptions.reverse
    ? [width - right, left]
    : [left, width - right];
  const yRange: [number, number] = yOptions.reverse
    ? [top, height - bottom]
    : [height - bottom, top];
  x.scale.range(xRange);
  y.scale.range(yRange);

  const project = (value: ChartValue, scale: ChartScaleInstance): number => {
    if (isPointScale(scale)) {
      return scale(value instanceof Date ? value.getTime() : value) ?? NaN;
    }
    return scale(numeric(value)) ?? NaN;
  };

  const grid: SceneGridLine[] = [];
  const ticks: SceneTick[] = [];

  if (!isPointScale(y.scale)) {
    for (const t of yTicks) {
      const py = y.scale(t) ?? 0;
      if (yOptions.grid) {
        grid.push({
          key: `gy-${t}`,
          x1: left,
          y1: py,
          x2: width - right,
          y2: py,
        });
      }
      if (showY) {
        ticks.push({
          key: `ty-${t}`,
          x: left - 8,
          y: py + 3.5,
          text: yFormat(t),
          anchor: 'end',
        });
      }
    }
  }

  const xTickValues: (string | number)[] = isPointScale(x.scale)
    ? x.scale.domain()
    : x.scale.ticks(Math.max(2, Math.floor((width - left - right) / 80)));
  const stride = Math.max(
    1,
    Math.ceil(
      // Thin category labels only below ~40px each.
      xTickValues.length / Math.max(1, Math.floor((width - left - right) / 40)),
    ),
  );
  xTickValues.forEach((t, i) => {
    const px = project(t, x.scale);
    if (!Number.isFinite(px)) return;
    if (xOptions.grid) {
      grid.push({
        key: `gx-${t}`,
        x1: px,
        y1: top,
        x2: px,
        y2: height - bottom,
      });
    }
    if (showX && i % stride === 0) {
      const text =
        typeof t === 'number' && !isPointScale(x.scale)
          ? x.scale.tickFormat()(t)
          : String(t);
      ticks.push({
        key: `tx-${t}`,
        x: px,
        y: height - bottom + 16,
        text,
        anchor: 'middle',
      });
    }
  });

  const paths = marks.flatMap((mark, index): ScenePath[] => {
    if (mark.points.length === 0) return [];
    const coords = mark.points.map((p) => ({
      x: project(p.x, x.scale),
      y: project(p.y, y.scale),
      y1: project(p.y1, y.scale),
    }));
    const line = `M${coords.map((c) => pt(c.x, c.y)).join('L')}`;
    const id = mark.id ?? `${mark.kind}-${index}`;
    if (mark.kind === 'areaY') {
      const base = [...coords]
        .reverse()
        .map((c) => pt(c.x, c.y1))
        .join('L');
      return [
        {
          key: id,
          d: `${line}L${base}Z`,
          fill: mark.fill ?? 'currentColor',
          fillOpacity: mark.fillOpacity,
          stroke: mark.stroke,
          strokeWidth: mark.strokeWidth,
          className: 'ts-chart__area',
        },
      ];
    }
    return [
      {
        key: id,
        d: line,
        fill: 'none',
        stroke: mark.stroke ?? 'currentColor',
        strokeOpacity: mark.strokeOpacity,
        strokeWidth: mark.strokeWidth ?? 1.5,
        strokeDasharray: mark.strokeDasharray,
        className: 'ts-chart__line',
      },
    ];
  });

  return { grid, ticks, paths };
}

function resolveLength(
  length: PolarLength | undefined,
  context: PolarLayoutContext,
  fallback: number,
): number {
  if (length === undefined) return fallback;
  return typeof length === 'function' ? length(context) : length;
}

const onCircle = (cx: number, cy: number, r: number, angle: number) =>
  pt(cx + r * Math.sin(angle), cy - r * Math.cos(angle));

/** SVG path for an annular sector; mirrors d3-shape's arc with cornerRadius. */
function arcPath(
  cx: number,
  cy: number,
  inner: number,
  outer: number,
  a0: number,
  a1: number,
  corner: number,
): string {
  const [start, end] = a0 <= a1 ? [a0, a1] : [a1, a0];
  const sweep = end - start;
  const r0 = Math.max(0, Math.min(inner, outer));
  const r1 = Math.max(inner, outer);
  if (r1 <= EPSILON || sweep <= EPSILON) return '';

  if (sweep >= TAU - EPSILON) {
    const ring = `M${pt(cx, cy - r1)}A${r1},${r1},0,1,1,${pt(cx, cy + r1)}A${r1},${r1},0,1,1,${pt(cx, cy - r1)}`;
    if (r0 <= EPSILON) return `${ring}Z`;
    return `${ring}M${pt(cx, cy - r0)}A${r0},${r0},0,1,0,${pt(cx, cy + r0)}A${r0},${r0},0,1,0,${pt(cx, cy - r0)}Z`;
  }

  const s = Math.sin(Math.min(sweep, Math.PI) / 2);
  const limits = [corner, (r1 - r0) / 2, (r1 * s) / (1 + s)];
  if (r0 > EPSILON && s < 1) limits.push((r0 * s) / (1 - s));
  const rc = Math.max(0, Math.min(...limits));

  if (rc <= EPSILON) {
    const large = sweep > Math.PI ? 1 : 0;
    const outerArc = `M${onCircle(cx, cy, r1, start)}A${r1},${r1},0,${large},1,${onCircle(cx, cy, r1, end)}`;
    if (r0 <= EPSILON) return `${outerArc}L${pt(cx, cy)}Z`;
    return `${outerArc}L${onCircle(cx, cy, r0, end)}A${r0},${r0},0,${large},0,${onCircle(cx, cy, r0, start)}Z`;
  }

  // Outer corners: circle of radius rc tangent to the outer arc and the edge.
  const dOuter = r1 - rc;
  const deltaOuter = Math.asin(rc / dOuter);
  const edgeOuter = dOuter * Math.cos(deltaOuter);
  const outerLarge = sweep - 2 * deltaOuter > Math.PI ? 1 : 0;
  let d =
    `M${onCircle(cx, cy, edgeOuter, start)}` +
    `A${rc},${rc},0,0,1,${onCircle(cx, cy, r1, start + deltaOuter)}` +
    `A${r1},${r1},0,${outerLarge},1,${onCircle(cx, cy, r1, end - deltaOuter)}` +
    `A${rc},${rc},0,0,1,${onCircle(cx, cy, edgeOuter, end)}`;

  if (r0 <= EPSILON) return `${d}L${pt(cx, cy)}Z`;

  // Inner corners: circle tangent to the inner arc (from outside) and the edge.
  const dInner = r0 + rc;
  const deltaInner = Math.asin(rc / dInner);
  const edgeInner = dInner * Math.cos(deltaInner);
  const innerLarge = sweep - 2 * deltaInner > Math.PI ? 1 : 0;
  d +=
    `L${onCircle(cx, cy, edgeInner, end)}` +
    `A${rc},${rc},0,0,1,${onCircle(cx, cy, r0, end - deltaInner)}` +
    `A${r0},${r0},0,${innerLarge},0,${onCircle(cx, cy, r0, start + deltaInner)}` +
    `A${rc},${rc},0,0,1,${onCircle(cx, cy, edgeInner, start)}Z`;
  return d;
}

function compilePolar(
  mark: PolarMark,
  width: number,
  height: number,
): ScenePath[] {
  const { options } = mark;
  const context: PolarLayoutContext = {
    centerX: width / 2,
    centerY: height / 2,
    radius: Math.max(
      0,
      (Math.min(width, height) / 2 - (options.inset ?? 0)) *
        (options.radiusRatio ?? 1),
    ),
    startAngle: options.startAngle ?? 0,
    endAngle: options.endAngle ?? TAU,
  };

  return options.marks.flatMap((arc: RadialArcMark, markIndex) => {
    const inner = resolveLength(arc.innerRadius, context, 0);
    const outer = resolveLength(arc.outerRadius, context, context.radius);
    const corner = resolveLength(arc.cornerRadius, context, 0);
    return arc.slices.flatMap((slice, index) => {
      const half = slice.padAngle / 2;
      const d = arcPath(
        context.centerX,
        context.centerY,
        inner,
        outer,
        slice.startAngle + half,
        slice.endAngle - half,
        corner,
      );
      if (!d) return [];
      return [
        {
          key: `${arc.id ?? `arc-${markIndex}`}:${index}`,
          d,
          fill: slice.fill ?? 'currentColor',
          fillOpacity: arc.fillOpacity,
          stroke: slice.stroke,
          strokeOpacity: arc.strokeOpacity,
          strokeWidth: arc.strokeWidth,
          opacity: arc.opacity,
          className: arc.className ?? 'ts-chart__arc',
        },
      ];
    });
  });
}

export function compileScene(
  definition: ChartDefinition,
  width: number,
  height: number,
): ChartScene {
  const cartesianMarks = definition.marks.filter(
    (m): m is LineYMark | AreaYMark => m.kind === 'lineY' || m.kind === 'areaY',
  );
  const cartesian = compileCartesian(definition, cartesianMarks, width, height);
  const polarPaths = definition.marks
    .filter((m): m is PolarMark => m.kind === 'polar')
    .flatMap((m) => compilePolar(m, width, height));
  return {
    width,
    height,
    grid: cartesian.grid,
    ticks: cartesian.ticks,
    paths: [...cartesian.paths, ...polarPaths],
  };
}

export * from './chart-backend';
export type {
  AreaYOptions,
  ChartDefinition,
  ChartProps,
  LineYOptions,
  PieDatum,
  PieOptions,
  PolarOptions,
  RadialArcOptions,
} from './types';

// Public types for the hand-rolled chart engine. Every name and option below
// mirrors @tanstack/charts 0.18.0 so a definition written for this engine also
// type-checks against TanStack Charts. Only a subset is implemented; options
// TanStack supports but this engine does not are deliberately absent, so using
// one fails type-checking instead of being silently ignored.
import type { StyleValue } from 'vue';

export type ChartValue = string | number | Date;
export type ChartKey = string | number;

export interface ChannelAccessorContext<TDatum> {
  index: number;
  data: readonly TDatum[];
}

export type ChannelAccessor<TDatum, TValue> = (
  datum: TDatum,
  context: ChannelAccessorContext<TDatum>,
) => TValue;

/** Keys of `TDatum` whose value type fits `TValue`. */
export type ChannelField<TDatum, TValue> = {
  [TKey in Extract<keyof TDatum, string>]-?: TDatum[TKey] extends TValue
    ? TKey
    : never;
}[Extract<keyof TDatum, string>];

export type Channel<TDatum, TValue> =
  | ChannelField<TDatum, TValue>
  | ChannelAccessor<TDatum, TValue>;

/** A constant, or an accessor evaluated per datum. */
export type VisualChannel<TDatum, TValue> =
  | TValue
  | ChannelAccessor<TDatum, TValue>;

export interface LinearScale {
  (value: number | null | undefined): number | undefined;
  domain(): [number, number];
  domain(values: Iterable<number>): LinearScale;
  range(): [number, number];
  range(values: Iterable<number>): LinearScale;
  invert(value: number): number;
  clamp(): boolean;
  clamp(value: boolean): LinearScale;
  ticks(count?: number): number[];
  tickFormat(count?: number): (value: number) => string;
  nice(count?: number): LinearScale;
  copy(): LinearScale;
}

export interface PointScale<TDomain extends string | number = string> {
  (value: TDomain | null | undefined): number | undefined;
  domain(): TDomain[];
  domain(values: Iterable<TDomain>): PointScale<TDomain>;
  range(): [number, number];
  range(values: Iterable<number>): PointScale<TDomain>;
  padding(): number;
  padding(value: number): PointScale<TDomain>;
  step(): number;
  copy(): PointScale<TDomain>;
}

export type ChartScaleInstance = LinearScale | PointScale<string | number>;
export type ChartScaleFactory = () => ChartScaleInstance;

export interface ChartAxisPresentationOptions {
  label?: string;
}

export interface ChartPositionScaleOptions {
  /** A factory infers its domain from the marks; an instance keeps its own. */
  scale: ChartScaleFactory | ChartScaleInstance;
  nice?: boolean | number;
  reverse?: boolean;
  grid?: boolean;
  /** False keeps the scale but omits the visible axis. */
  axis?: false | ChartAxisPresentationOptions;
}

/** Unused scales must be declared `null`, as TanStack Charts requires. */
export type ChartScales = Readonly<
  Record<string, ChartPositionScaleOptions | null>
>;

interface MarkStrokeOptions<TDatum> {
  stroke?: VisualChannel<TDatum, string>;
  strokeOpacity?: number;
  strokeWidth?: number;
  strokeDasharray?: string;
}

export interface LineYOptions<TDatum> extends MarkStrokeOptions<TDatum> {
  id?: string;
  x?: Channel<TDatum, ChartValue | null | undefined>;
  y?: Channel<TDatum, number | null | undefined>;
}

export interface AreaYOptions<TDatum> {
  id?: string;
  x?: Channel<TDatum, ChartValue | null | undefined>;
  y?: Channel<TDatum, number | null | undefined>;
  y1?: number | Channel<TDatum, number | null | undefined>;
  fill?: VisualChannel<TDatum, string>;
  fillOpacity?: number;
  stroke?: VisualChannel<TDatum, string>;
  strokeWidth?: number;
}

export interface PolarLayoutContext {
  centerX: number;
  centerY: number;
  radius: number;
  startAngle: number;
  endAngle: number;
}

/** Pixels, or a function of the resolved polar layout. */
export type PolarLength = number | ((context: PolarLayoutContext) => number);

export interface RadialArcOptions<TDatum> {
  id?: string;
  className?: string;
  startAngle?: Channel<TDatum, number | null | undefined>;
  endAngle?: Channel<TDatum, number | null | undefined>;
  padAngle?: Channel<TDatum, number | null | undefined>;
  innerRadius?: PolarLength;
  outerRadius?: PolarLength;
  cornerRadius?: PolarLength;
  fill?: VisualChannel<TDatum, string>;
  fillOpacity?: number;
  stroke?: VisualChannel<TDatum, string>;
  strokeOpacity?: number;
  strokeWidth?: number;
  opacity?: number;
}

export type TransformValue<TDatum, TValue> =
  | {
      [TKey in Extract<keyof TDatum, string>]-?: NonNullable<
        TDatum[TKey]
      > extends TValue
        ? TKey
        : never;
    }[Extract<keyof TDatum, string>]
  | ChannelAccessor<TDatum, TValue>;

export interface PieOptions<TDatum> {
  readonly value: TransformValue<TDatum, number | null | undefined>;
  /** Overall start angle in radians. Defaults to 0 at 12 o'clock. */
  readonly startAngle?: number;
  /** Overall end angle in radians. Defaults to 2π. */
  readonly endAngle?: number;
  /** Empty angle between visible slices. Defaults to 0. */
  readonly gapAngle?: number;
}

type PieDerivedField =
  | 'value'
  | 'index'
  | 'fraction'
  | 'startAngle'
  | 'endAngle'
  | 'angle'
  | 'padAngle'
  | 'source'
  | 'sourceIndexes';

export type PieDatum<TDatum extends object> = Omit<TDatum, PieDerivedField> & {
  readonly source: readonly TDatum[];
  readonly sourceIndexes: readonly number[];
  readonly value: number;
  readonly index: number;
  readonly fraction: number;
  readonly startAngle: number;
  readonly endAngle: number;
  readonly angle: number;
  readonly padAngle: 0;
};

export type PolarScales = Readonly<Record<string, null>>;

// Internal mark records. Builders evaluate every channel while the datum type
// is still known, so a mark stores only render-ready values and carries no
// datum generic. Marks over different datum types then share one list.
export interface CartesianPoint {
  readonly x: ChartValue;
  readonly y: number;
  readonly y1: number;
}

export interface LineYMark {
  readonly kind: 'lineY';
  readonly id?: string;
  readonly points: readonly CartesianPoint[];
  readonly stroke?: string;
  readonly strokeOpacity?: number;
  readonly strokeWidth?: number;
  readonly strokeDasharray?: string;
}

export interface AreaYMark {
  readonly kind: 'areaY';
  readonly id?: string;
  readonly points: readonly CartesianPoint[];
  readonly fill?: string;
  readonly fillOpacity?: number;
  readonly stroke?: string;
  readonly strokeWidth?: number;
}

export interface ArcSlice {
  readonly startAngle: number;
  readonly endAngle: number;
  readonly padAngle: number;
  readonly fill?: string;
  readonly stroke?: string;
}

export interface RadialArcMark {
  readonly kind: 'radialArc';
  readonly id?: string;
  readonly className?: string;
  readonly slices: readonly ArcSlice[];
  readonly innerRadius?: PolarLength;
  readonly outerRadius?: PolarLength;
  readonly cornerRadius?: PolarLength;
  readonly fillOpacity?: number;
  readonly strokeOpacity?: number;
  readonly strokeWidth?: number;
  readonly opacity?: number;
}

export interface PolarOptions {
  id?: string;
  className?: string;
  marks: readonly RadialArcMark[];
  scales: PolarScales;
  startAngle?: number;
  endAngle?: number;
  /** Pixel inset applied before radiusRatio. */
  inset?: number;
  /** Multiplier applied to the final available radius. Defaults to 1. */
  radiusRatio?: number;
}

export interface PolarMark {
  readonly kind: 'polar';
  readonly options: PolarOptions;
}

export type ChartMark = LineYMark | AreaYMark | PolarMark;

export interface ChartSpec {
  marks: readonly ChartMark[];
  scales: ChartScales;
}

export interface ChartDefinition {
  readonly marks: readonly ChartMark[];
  readonly scales: ChartScales;
}

export interface ChartHostProps {
  definition: ChartDefinition;
  /**
   * Required, as in TanStack Charts. Pass it as `v-bind="{ ariaLabel }"`: Vue's
   * type checker reads a literal `aria-label` as an HTML attribute, not this prop.
   */
  ariaLabel: string;
  ariaDescription?: string;
  height?: number;
  width?: number;
  /** Width / height, used when `height` is omitted. */
  aspectRatio?: number;
  /** Width used for the server render before the container is measured. */
  initialWidth?: number;
}

/** Host props plus presentation props, typed as in TanStack Charts. */
export interface ChartProps extends ChartHostProps {
  class?: string;
  style?: StyleValue;
}

// Scene: the renderer-neutral output of compiling a definition at a size.
export interface ScenePath {
  readonly key: string;
  readonly d: string;
  readonly fill: string;
  readonly fillOpacity?: number;
  readonly stroke?: string;
  readonly strokeOpacity?: number;
  readonly strokeWidth?: number;
  readonly strokeDasharray?: string;
  readonly opacity?: number;
  readonly className?: string;
}

export interface SceneGridLine {
  readonly key: string;
  readonly x1: number;
  readonly y1: number;
  readonly x2: number;
  readonly y2: number;
}

export interface SceneTick {
  readonly key: string;
  readonly x: number;
  readonly y: number;
  readonly text: string;
  readonly anchor: 'start' | 'middle' | 'end';
}

export interface ChartScene {
  readonly width: number;
  readonly height: number;
  readonly grid: readonly SceneGridLine[];
  readonly ticks: readonly SceneTick[];
  readonly paths: readonly ScenePath[];
}

import { computed, onMounted, ref, toValue, watch } from 'vue';
import type { ComputedRef, MaybeRefOrGetter } from 'vue';
import {
  TransitionPresets,
  usePreferredReducedMotion,
  useTransition,
} from '@vueuse/core';

/**
 * Tweens a number from 0 to `target` after mount, then follows it.
 * Charts animate by tweening their data, never the rendered SVG, so the same
 * motion works with the hand-rolled engine and with TanStack Charts.
 * The server render starts at 0; with reduced motion the value jumps to
 * `target` on mount instead of tweening.
 */
export function useChartTween(
  target: MaybeRefOrGetter<number>,
  duration = 900,
): ComputedRef<number> {
  const motion = usePreferredReducedMotion();
  const reduce = computed(() => motion.value === 'reduce');
  const source = ref(0);

  onMounted(() => {
    source.value = toValue(target);
  });
  watch(
    () => toValue(target),
    (value) => {
      source.value = value;
    },
  );

  return useTransition(source, {
    duration,
    transition: TransitionPresets.easeOutCubic,
    disabled: reduce,
  });
}
